def _parse(v):
    if '+' in v:
        v = v.split('+', 1)[0]
    if '-' in v:
        core, pre = v.split('-', 1)
        pre_ids = pre.split('.')
    else:
        core, pre_ids = v, None
    major, minor, patch = (int(x) for x in core.split('.'))
    return major, minor, patch, pre_ids


def _cmp_pre(a, b):
    if a is None and b is None:
        return 0
    if a is None:
        return 1
    if b is None:
        return -1
    for x, y in zip(a, b):
        xn, yn = x.isdigit(), y.isdigit()
        if xn and yn:
            ix, iy = int(x), int(y)
            if ix != iy:
                return -1 if ix < iy else 1
        elif xn:
            return -1
        elif yn:
            return 1
        else:
            if x != y:
                return -1 if x < y else 1
    if len(a) != len(b):
        return -1 if len(a) < len(b) else 1
    return 0


def _cmp(u, v):
    a, b = _parse(u), _parse(v)
    for x, y in zip(a[:3], b[:3]):
        if x != y:
            return -1 if x < y else 1
    return _cmp_pre(a[3], b[3])


def sort_versions(vs):
    return sorted(vs, key=cmp_to_key(_cmp))
